CREATE TABLE room_type_inventory (hotel_id BIGINT NOT NULL, room_type_id VARCHAR(100) NOT NULL, date DATE NOT NULL, total_inventory INT NOT NULL CHECK(total_inventory >= 0), total_reserved INT NOT NULL DEFAULT 0 CHECK(total_reserved >= 0), version BIGINT NOT NULL DEFAULT 0, PRIMARY KEY(hotel_id,room_type_id,date));
CREATE TABLE reservation (reservation_id BIGSERIAL PRIMARY KEY, hotel_id BIGINT NOT NULL, room_type_id VARCHAR(100) NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, status VARCHAR(20) NOT NULL, guest_id BIGINT NOT NULL, total_amount DECIMAL(10,2) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK(end_date > start_date));
CREATE INDEX idx_reservation_guest_id ON reservation(guest_id); CREATE INDEX idx_reservation_hotel_id ON reservation(hotel_id);
